css:
.fx-faq{width:min(760px,100%);display:grid;gap:1.6em}
.fx-faq h2{font-size:clamp(2em,4.6vw,3em);text-align:center}
.fx-faq .it{border-bottom:1px solid var(--border)}
.fx-faq button{all:unset;box-sizing:border-box;width:100%;display:flex;justify-content:space-between;align-items:center;gap:1em;padding:1.2em .2em;cursor:pointer;font:600 1.12em var(--font-heading)}
.fx-faq button:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:var(--radius)}
.fx-faq .ic{flex:none;width:1.7em;height:1.7em;border-radius:50%;border:1.5px solid var(--primary);display:grid;place-items:center;position:relative;transition:transform calc(.35s/var(--speed)),background .3s}
.fx-faq .ic::before,.fx-faq .ic::after{content:"";position:absolute;width:.7em;height:1.5px;background:var(--primary);transition:inherit}.fx-faq .ic::after{transform:rotate(90deg)}
.fx-faq .it.open .ic{transform:rotate(180deg);background:var(--primary)}.fx-faq .it.open .ic::before,.fx-faq .it.open .ic::after{background:var(--on-primary)}.fx-faq .it.open .ic::after{transform:rotate(0)}
.fx-faq .pn{display:grid;grid-template-rows:0fr;transition:grid-template-rows calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-faq .it.open .pn{grid-template-rows:1fr}.fx-faq .pn>div{overflow:hidden}.fx-faq .pn p{padding:0 .2em 1.4em;opacity:.72;max-width:60ch}
@media(prefers-reduced-motion:reduce){.fx-faq .pn,.fx-faq .ic{transition:none}}
